// Fork-only validation: preserve the published JS/native API pair while exercising new packaging.
'use strict';
const fs = require('node:fs');
const os = require('node:os');
const path = require('node:path');
const assert = require('node:assert/strict');
const crypto = require('node:crypto');
const { execFileSync } = require('node:child_process');
const { packPlatforms, findNpmCli } = require('../../js/node/script/pack-platforms.js');
const scratch = fs.mkdtempSync(path.join(os.tmpdir(), 'ort-native-smoke-'));
const npm = (args, cwd) => execFileSync(process.execPath, [findNpmCli(), ...args], { cwd, encoding: 'utf8' });
const npmOptions = ['--ignore-scripts', '--no-audit', '--no-fund'];
const json = (filename) => JSON.parse(fs.readFileSync(filename));
const writeJson = (filename, value) => fs.writeFileSync(filename, JSON.stringify(value));
const hash = (filename) => crypto.createHash('sha256').update(fs.readFileSync(filename)).digest('hex');
const bytes = (tag, value) => Buffer.concat([Buffer.from([tag, value.length]), value]);
const text = (tag, value) => bytes(tag, Buffer.from(value));
const shape = bytes(0x12, bytes(0x0a, Buffer.from([0x08, 0x02])));
const type = bytes(0x12, bytes(0x0a, Buffer.concat([Buffer.from([0x08, 0x01]), shape])));
const valueInfo = (name) => Buffer.concat([text(0x0a, name), type]);
const node = Buffer.concat([text(0x0a, 'input'), text(0x12, 'output'), text(0x22, 'Identity')]);
const graph = Buffer.concat([bytes(0x0a, node), text(0x12, 'identity'), bytes(0x5a, valueInfo('input')), bytes(0x62, valueInfo('output'))]);
const model = Buffer.concat([Buffer.from([0x08, 0x09]), bytes(0x42, Buffer.from([0x10, 0x0d])), bytes(0x3a, graph)]);
const main = async () => {
  const [originalArchive] = JSON.parse(npm(['pack', 'onnxruntime-node@1.30.0', '--json', '--ignore-scripts'], scratch));
  const originalPath = path.join(scratch, originalArchive.filename);
  const baseline = path.join(scratch, 'baseline');
  fs.mkdirSync(baseline);
  writeJson(path.join(baseline, 'package.json'), { name: 'baseline', private: true, dependencies: { 'onnxruntime-node': `file:${originalPath}` } });
  npm(['install', ...npmOptions], baseline);
  const run = (root) => JSON.parse(execFileSync(process.execPath, [__filename, 'infer', root, model.toString('base64')], { encoding: 'utf8' }));
  const baselineOutput = await run(baseline);
  const repack = path.join(scratch, 'repack');
  fs.mkdirSync(repack);
  execFileSync('tar', ['-xzf', originalPath, '-C', repack]);
  const packageRoot = path.join(repack, 'package');
  fs.copyFileSync('js/node/script/native-directory.js', path.join(packageRoot, 'script/native-directory.js'));
  const bindingFile = path.join(packageRoot, 'dist/binding.js');
  const source = fs.readFileSync(bindingFile, 'utf8');
  const patched = source.replace(/require\(`\.\.\/bin\/napi-v6\/\$\{process.platform\}\/\$\{process.arch\}\/onnxruntime_binding.node`\)/, "require(require('../script/native-directory.js').getNativeBindingPath())");
  assert.notEqual(patched, source, 'Published loader pattern must be found');
  fs.writeFileSync(bindingFile, patched);
  const archives = packPlatforms(packageRoot, path.join(scratch, 'archives'));
  const parent = archives.find((entry) => entry.name === 'onnxruntime-node');
  const consumer = path.join(scratch, 'split');
  fs.mkdirSync(consumer);
  const overrides = Object.fromEntries(archives.filter((entry) => entry !== parent).map((entry) => [entry.name, `file:${path.join(scratch, 'archives', entry.filename)}`]));
  writeJson(path.join(consumer, 'package.json'), { name: 'consumer', private: true, dependencies: { 'onnxruntime-node': `file:${path.join(scratch, 'archives', parent.filename)}` }, overrides });
  npm(['install', ...npmOptions], consumer);
  const splitOutput = await run(consumer);
  assert.deepEqual(baselineOutput, [1.5, -2.5]);
  assert.deepEqual(splitOutput, baselineOutput);
  const nativeName = `onnxruntime-node-${process.platform}-${process.arch}`;
  assert.deepEqual(fs.readdirSync(path.join(consumer, 'node_modules')).filter((name) => name.startsWith('onnxruntime-node-')), [nativeName]);
  const originalNative = path.join(packageRoot, 'bin/napi-v6', process.platform, process.arch);
  const selectedNative = path.join(consumer, 'node_modules', nativeName, 'bin/napi-v6', process.platform, process.arch);
  const nativeHashes = Object.fromEntries(fs.readdirSync(originalNative).map((name) => {
    const original = hash(path.join(originalNative, name));
    assert.equal(hash(path.join(selectedNative, name)), original);
    return [name, original];
  }));
  let pnpmCrossTarget;
  if (process.platform === 'linux') {
    const cross = path.join(scratch, 'cross');
    fs.mkdirSync(cross);
    writeJson(path.join(cross, 'package.json'), { name: 'cross-target', private: true, dependencies: { 'onnxruntime-node': `file:${path.join(scratch, 'archives', parent.filename)}` } });
    fs.writeFileSync(path.join(cross, 'pnpm-workspace.yaml'), `supportedArchitectures:\n  os: [linux]\n  cpu: [arm64]\n  libc: [glibc]\noverrides:\n${Object.entries(overrides).map(([name, value]) => `  ${JSON.stringify(name)}: ${JSON.stringify(value)}`).join('\n')}\n`);
    const globalRoot = npm(['root', '--global'], scratch).trim();
    const pnpmManifest = json(path.join(globalRoot, 'pnpm/package.json'));
    const pnpmBin = typeof pnpmManifest.bin === 'string' ? pnpmManifest.bin : pnpmManifest.bin.pnpm;
    execFileSync(path.join(globalRoot, 'pnpm', pnpmBin), ['install', '--ignore-scripts', '--reporter=append-only'], { cwd: cross, encoding: 'utf8' });
    const crossParent = path.dirname(require.resolve('onnxruntime-node/package.json', { paths: [cross] }));
    const { getNativeBindingPath } = require(path.join(crossParent, 'script/native-directory.js'));
    const crossBinding = getNativeBindingPath(crossParent, 'linux', 'arm64');
    assert.equal(hash(crossBinding), hash(path.join(packageRoot, 'bin/napi-v6/linux/arm64/onnxruntime_binding.node')));
    assert.throws(() => getNativeBindingPath(crossParent, 'linux', 'x64'), /Missing onnxruntime-node-linux-x64/);
    assert.throws(() => getNativeBindingPath(crossParent, 'win32', 'x64'), /Missing onnxruntime-node-win32-x64/);
    pnpmCrossTarget = { packageManager: 'pnpm@11.28.1', os: 'linux', cpu: 'arm64', libc: 'glibc', bindingSha256: hash(crossBinding), otherTargetsAbsent: true };
  }
  const result = { pnpmCrossTarget, platform: process.platform, arch: process.arch, referenceVersion: '1.30.0', referenceArchiveSha256: hash(originalPath), modelSha256: crypto.createHash('sha256').update(model).digest('hex'), baselineOutput, splitOutput, nativeHashes, originalUnpackedSize: originalArchive.unpackedSize, parentUnpackedSize: parent.unpackedSize, nativeUnpackedSize: archives.find((entry) => entry.name === nativeName).unpackedSize };
  writeJson('platform-smoke.json', result);
  process.stdout.write(`${JSON.stringify(result, null, 2)}\n`);
};
const infer = async () => {
  const ort = require(require.resolve('onnxruntime-node', { paths: [process.argv[3]] }));
  const session = await ort.InferenceSession.create(Buffer.from(process.argv[4], 'base64'), { executionProviders: ['cpu'] });
  const result = await session.run({ input: new ort.Tensor('float32', Float32Array.from([1.5, -2.5]), [2]) });
  const output = [...result.output.data];
  await session.release();
  process.stdout.write(JSON.stringify(output));
};
const operation = process.argv[2] === 'infer' ? infer() : main();
operation.finally(() => fs.rmSync(scratch, { recursive: true, force: true })).catch((error) => { console.error(error); process.exitCode = 1; });
